import '../App.css';  // Hero에 필요한 스타일 불러오기

function Hero() {
  return (
    <section className="hero">
      <h1>AI-driven Interior Proposals in Minutes</h1>
      <p>ASSEMBLE은 사용자의 요청사항에 맞게 인테리어를 추천합니다.</p>
      <div>
        <button className="btn-primary">Get Started</button>
      </div>
    </section>
  );
}

export default Hero;
